const normalizeSearch = value => String(value ?? "").normalize("NFKC").toLowerCase().replace(/[ァ-ヶ]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x60)).replace(/\s+/g, "");
export function searchCharacterVariants(query, limit = 30) {
  const q = normalizeSearch(query);
  if (!q) return CHARACTER_VARIANT_MASTER.slice(0, limit);
  return CHARACTER_VARIANT_MASTER.filter(item => normalizeSearch(item.searchText).includes(q)).slice(0, limit);
}
export function getCharacterVariant(variantId) { return CHARACTER_VARIANT_MASTER.find(item => item.variantId === variantId) ?? null; }
export function getCharacter(characterId) { return CHARACTER_MASTER.find(item => item.characterId === characterId) ?? null; }
